import fs from 'node:fs';
import path from 'node:path';
import { ENV_DECLARATIONS } from '../envConfig.ts';

const SUBSYSTEM_LABELS: Record<string, string> = {
  core: 'Core services',
  'write-auth': 'Write authorization and request limits',
  telemetry: 'Telemetry and source maps',
  'live-audio': 'Live speech translation',
  slides: 'Slide translation',
  session: 'Current session',
  storage: 'Persistent storage',
  landing: 'Landing page',
  testing: 'Testing',
  deployment: 'Deployment',
};

const lines = [
  '# Generated by scripts/generate-env-template.ts; do not edit this file directly.',
  '# Run "npm run env:generate" after changing envConfig.ts.',
  '',
];

for (const subsystem of [
  'core', 'write-auth', 'telemetry', 'live-audio', 'slides', 'session',
  'storage', 'landing', 'testing', 'deployment',
] as const) {
  const entries = ENV_DECLARATIONS.filter((entry) => entry.subsystem === subsystem);
  if (entries.length === 0) continue;
  lines.push(`# ${SUBSYSTEM_LABELS[subsystem]}`);
  for (const entry of entries) {
    lines.push(`# ${entry.description}`);
    if (entry.required) {
      lines.push(`${entry.name}=${entry.placeholder ?? ''}`);
    } else {
      lines.push(`# ${entry.name}${entry.defaultValue !== undefined ? `=${entry.defaultValue}` : '='}`);
    }
  }
  lines.push('');
}

const target = path.resolve(process.cwd(), 'template-.env');
fs.writeFileSync(target, `${lines.join('\n').trimEnd()}\n`);
console.log(`Generated ${path.relative(process.cwd(), target)} from envConfig.ts`);
